content.content:
1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>FirstRun: Docs that work (literally)</title>
7	<link rel="stylesheet" href="assets/site-nav.css">
8	<meta name="description" content="Paste a docs URL. Your coding agent runs the quickstart in a clean container, finds the first step that breaks, fixes it, and proves the fix. Built for neatHack 2026.">
9	<meta name="color-scheme" content="light">
10	<script>document.documentElement.className="js"</script>
11	<meta property="og:type" content="website">
12	<meta property="og:title" content="FirstRun: Docs that work (literally).">
13	<meta property="og:description" content="FirstRun runs your quickstart in a clean container, finds the first step that breaks, and proves the fix with a second clean run.">
14	<meta property="og:image" content="assets/og-card-1200x630.jpg">
15	<meta name="twitter:card" content="summary_large_image">
16	<link rel="icon" href="assets/logo.svg" type="image/svg+xml">
17	<link rel="preconnect" href="https://fonts.googleapis.com">
18	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
19	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&family=Geist+Mono:wght@400;500;600&display=swap">
20	<style>
21	:root{--page:#F4F5F9;--surface:#FBFBFD;--ink:#1D1D1F;--muted:#65656B;--accent:#0A66D6;--accent-d:#0856B5;--tint:#E6F0FC;--pass:#1B8A3A;--bad:#C4281C;--hair:rgba(29,29,31,.08);--road:rgba(29,29,31,.09);--ease:cubic-bezier(.16,1,.3,1);--pad:clamp(40px,5vw,60px);
22	--gl:var(--surface);--gl-f:none;
23	--edge:0 0 0 1px var(--hair);
24	--lift:0 1px 2px rgba(20,30,60,.05),0 8px 24px -12px rgba(30,50,110,.14)}
25	*{box-sizing:border-box;margin:0}
26	html{background:var(--page);color:var(--ink);font-family:Geist,-apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",Roboto,sans-serif;-webkit-text-size-adjust:100%;scroll-behavior:smooth;scroll-padding-top:84px}
27	body{line-height:1.45;font-size:17px;overflow-x:hidden;-webkit-font-smoothing:antialiased;position:relative}
28	code,pre,.mono{font-family:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
29	a{color:var(--accent);text-underline-offset:3px}
30	a:focus-visible,button:focus-visible,input:focus-visible,[role=tab]:focus-visible,pre:focus-visible{outline:3px solid var(--accent);outline-offset:3px;border-radius:12px}
31	section{max-width:960px;margin:0 auto;padding:var(--pad) 24px}
32	h1{font-size:clamp(38px,7vw,74px);line-height:1.03;letter-spacing:-.045em;font-weight:700}
33	h2{font-size:clamp(26px,4vw,40px);line-height:1.08;letter-spacing:-.035em;font-weight:700;margin-bottom:12px}
34	.lede{font-size:clamp(17px,2vw,21px);color:var(--muted);max-width:31em;margin-top:12px;line-height:1.4}
35	/* liquid glass: translucent fill, bright top edge, soft lift, specular corner */
36	.gl,.hit,.panel,.tool,.cli,.watch a,.links a,.nav,.box,.chips button,.twitter-tweet{background:var(--gl);-webkit-backdrop-filter:var(--gl-f);backdrop-filter:var(--gl-f);box-shadow:var(--edge),var(--lift)}
37	.hit,.panel,.tool,.box,.cli{position:relative}
38	.hit>*,.panel>*,.tool>*,.box>*{position:relative}
39	/* motion */
40	html.js .rv{opacity:0;transform:translateY(12px);transition:opacity .5s var(--ease),transform .5s var(--ease)}
41	html.js .rv.in{opacity:1;transform:none}
42	@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
43	@keyframes spin{to{transform:rotate(360deg)}}
44	/* nav: floating glass pill */
45	.nav{position:sticky;top:12px;z-index:30;height:54px;width:min(980px,calc(100% - 24px));margin:12px auto 0;border-radius:99px;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:0 9px 0 16px}
46	.wm{display:inline-flex;align-items:center;gap:9px;font-weight:700;font-size:16px;color:var(--ink);text-decoration:none;letter-spacing:-.025em}
47	.lg{width:28px;height:28px;display:block;filter:drop-shadow(0 3px 6px rgba(10,102,214,.35))}
48	.nl{display:flex;gap:4px;font-size:13.5px}
49	.nl a{color:var(--muted);text-decoration:none;padding:7px 13px;border-radius:99px;transition:color .2s,background .25s}
50	.nl a:hover{color:var(--ink);background:rgba(255,255,255,.65)}
51	.nav .sm{min-height:36px;padding:6px 18px;font-size:14px;border-radius:99px}
52	/* hero */
53	#hero{position:relative;padding-top:clamp(30px,5vw,56px);padding-bottom:clamp(18px,3vw,30px);text-align:center;max-width:1180px}
54	#hero>*{animation:rise .8s var(--ease) both}
55	#hero>:nth-child(2){animation-delay:.05s}#hero>:nth-child(3){animation-delay:.1s}#hero>:nth-child(4){animation-delay:.15s}#hero>:nth-child(5){animation-delay:.2s}
56	.icon{width:clamp(64px,8vw,84px);height:auto;margin:0 auto 22px;display:block;filter:drop-shadow(0 14px 22px rgba(10,102,214,.38));animation:rise .8s var(--ease) both}
57	#hero .lede{margin-left:auto;margin-right:auto}
58	.box{display:flex;gap:8px;align-items:center;margin:26px auto 0;max-width:640px;border-radius:99px;padding:7px 7px 7px 24px;transition:box-shadow .3s var(--ease)}
59	.box:focus-within{box-shadow:var(--edge),0 0 0 3px var(--accent),var(--lift)}
60	.box input{flex:1;min-width:0;font:inherit;font-size:18px;border:0;background:none;color:var(--ink);padding:10px 0;outline:0}
61	.box input::placeholder{color:#76767c}
62	button,.btn{font:inherit;font-weight:600;font-size:15px;background:linear-gradient(180deg,#2B86F0,#0A66D6);color:#fff;border:0;border-radius:99px;padding:10px 22px;cursor:pointer;min-height:46px;white-space:nowrap;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;box-shadow:inset 0 1px 0 rgba(255,255,255,.45),0 6px 16px -4px rgba(10,102,214,.55);transition:filter .2s,transform .25s var(--ease)}
63	button:hover,.btn:hover{filter:brightness(1.07)}
64	button:active,.btn:active{transform:scale(.96)}
65	.chips{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin-top:16px}
66	.chips button{background:var(--gl);color:var(--ink);border-radius:99px;font-weight:500;font-size:14px;padding:4px 16px;min-height:38px;box-shadow:var(--edge),0 4px 14px -6px rgba(30,50,110,.18)}
67	.chips button:hover{color:var(--accent);filter:none;transform:translateY(-2px)}
68	.chips .lbl{color:var(--muted);font-size:14px;align-self:center}
69	.hint{color:var(--muted);font-size:14px;margin-top:12px;min-height:1.45em}
70	.hint.cached{color:var(--pass);font-weight:500}
71	/* stickers */
72	#out{padding-top:8px;padding-bottom:var(--pad)}
73	.hit{border-radius:28px;padding:24px 26px;margin-bottom:20px}
74	.hit[hidden],.fresh[hidden]{display:none}
75	.hit-top{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;color:var(--muted);font-size:14px}
76	.pill{display:inline-flex;align-items:center;gap:6px;font-weight:600;font-size:13px;border-radius:99px;padding:3px 11px;background:rgba(27,138,58,.12);color:var(--pass)}
77	.pill:before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
78	.pill.other{background:var(--tint);color:var(--accent)}
79	.hit h3{font-size:clamp(22px,3.2vw,30px);letter-spacing:-.03em;line-height:1.15;margin-top:12px}
80	.hit p{color:var(--muted);margin-top:6px;max-width:38em}
81	.hit-act{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;margin-top:18px}
82	.hit-act span{color:var(--muted);font-size:14px}
83	.fresh{font-size:16px;letter-spacing:-.01em;color:var(--muted);font-weight:600;margin:0 0 10px 6px}
84	.panel{border-radius:28px;overflow:hidden}
85	.tabs{display:flex;gap:2px;padding:8px 10px 0;box-shadow:0 1px 0 var(--hair);align-items:flex-end}
86	.tabs [role=tab]{font:inherit;font-size:14px;font-weight:600;color:var(--muted);background:none;border:0;border-radius:12px 12px 0 0;padding:8px 14px;min-height:42px;cursor:pointer;box-shadow:none}
87	.tabs [role=tab]:hover{background:none;color:var(--ink);filter:none}
88	.tabs [role=tab][aria-selected=true]{color:var(--accent);box-shadow:inset 0 -2px 0 var(--accent)}
89	.tabs .sp{flex:1}
90	.tabs .cp{margin:0 4px 6px 0;padding:6px 18px;min-height:36px;font-size:14px;color:#fff}
91	.how{padding:12px 22px 0;color:var(--muted);font-size:14px}
92	pre{white-space:pre-wrap;word-break:break-word;font-size:14px;line-height:1.6;padding:10px 22px 22px;max-height:420px;overflow:auto;color:var(--ink)}
93	.strip{list-style:none;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:12px 16px;margin-top:20px;counter-reset:s}
94	.strip li{counter-increment:s;font-size:15px;color:var(--ink);line-height:1.35}
95	.strip li:before{content:counter(s);display:block;font-family:"Geist Mono",ui-monospace,Consolas,monospace;font-size:12px;color:var(--accent);font-weight:600;margin-bottom:3px}
96	.strip li span{color:var(--muted)}
97	/* film: full bleed, no frame, edges melt into the page */
98	#film{max-width:none;padding:8px 0 clamp(8px,2vw,24px)}
99	.reel{position:relative;max-width:1680px;margin:0 auto;aspect-ratio:2/1}
100	.reel video{display:block;width:100%;height:100%;object-fit:cover;background:#F3F3F5;border:0;border-radius:0;box-shadow:none;outline:0;-webkit-mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent),linear-gradient(180deg,transparent,#000 11%,#000 89%,transparent);-webkit-mask-composite:source-in;mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent),linear-gradient(180deg,transparent,#000 11%,#000 89%,transparent);mask-composite:intersect;mix-blend-mode:multiply}
101	.ctl{position:absolute;right:max(20px,8%);bottom:9%;display:flex;gap:8px}
102	.ctl button{min-height:36px;padding:4px 16px;font-size:13px;background:var(--gl);color:var(--ink);box-shadow:var(--edge),0 6px 18px -6px rgba(30,50,110,.25)}
103	.dl{text-align:center;font-size:13px;color:var(--muted);margin-top:2px}
104	/* steps */
105	.rrp{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(20px,3.5vw,34px);margin-top:26px}
106	.rrp figure{position:relative;border-radius:22px;overflow:hidden;aspect-ratio:16/10;display:flex;align-items:center;justify-content:center;background:#F3F3F4;box-shadow:var(--edge),var(--lift)}
107	.rrp img{width:100%;height:100%;object-fit:contain;display:block}
108	.rrp h3{font-size:24px;letter-spacing:-.03em;margin-top:14px}
109	.rrp p{color:var(--muted);font-size:15px;margin-top:4px}
110	/* watch */
111	.watch{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}
112	.watch a{display:inline-block;text-decoration:none;color:var(--ink);border-radius:20px;padding:12px 18px;font-weight:600;transition:transform .3s var(--ease),color .2s}
113	.watch a[hidden]{display:none}
114	.rl{margin:26px 0 8px}.rl h3{font-size:15px;color:var(--muted);font-weight:600;margin-bottom:10px}
115	.rl ol{list-style:none;padding:0;display:grid;gap:8px;margin-bottom:14px}
116	.rl li{display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center;border-radius:16px;padding:11px 16px;background:var(--gl);box-shadow:var(--edge),var(--lift);font-size:15px}
117	.rl li b{font-weight:600}.rl li span{color:var(--muted);font-size:13.5px}
118	.rl .dot{width:10px;height:10px;border-radius:50%;background:var(--pass)}.rl .dot.f{background:var(--bad)}
119	.rl a.go{font-weight:600;text-decoration:none;font-size:14px}
120	.chain{display:flex;flex-wrap:wrap;gap:8px;align-items:stretch;margin:22px 0 6px;padding:0;list-style:none}
121	.chain li{flex:1 1 190px;border-radius:16px;padding:14px 16px;background:var(--gl);box-shadow:var(--edge),var(--lift);font-size:15px;position:relative}
122	.chain li b{display:block;font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:var(--accent);margin-bottom:4px}
123	.chain li.hot{box-shadow:var(--edge),0 0 0 2px var(--accent),var(--lift)}
124	.why3{margin-top:14px;font-size:15px;color:var(--muted)}
125	
126	.watch a small{display:block;font-weight:400;color:var(--muted);font-size:13px}
127	.watch a:hover{color:var(--accent);transform:translateY(-3px)}
128	.cli{border-radius:22px;padding:16px 22px;margin-top:14px;font-size:14px;line-height:1.8;overflow-x:auto;white-space:pre}
129	.cli .p,.cli .c{color:var(--muted)}
130	.cli .p{user-select:none}
131	.cap{color:var(--muted);font-size:14px;margin-top:10px}
132	/* tools */
133	.tools{display:grid;gap:14px;margin-top:26px}
134	.tool{border-radius:30px;padding:clamp(20px,3vw,28px);display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.35fr);gap:clamp(20px,3.5vw,32px);align-items:center}
135	.tool:nth-child(even) .txt{order:2}
136	.tool header{display:flex;align-items:center;gap:10px}
137	.tool img.lg2{width:38px;height:38px;border-radius:10px;display:block;box-shadow:0 4px 12px -2px rgba(0,0,0,.25)}
138	.tool h3{font-size:20px;letter-spacing:-.025em}
139	.tool .job{color:var(--ink);font-size:clamp(22px,2.8vw,28px);font-weight:700;letter-spacing:-.03em;line-height:1.15;margin-top:16px}
140	.tool p{color:var(--muted);font-size:15px;margin-top:6px}
141	.tool figure{border-radius:16px;overflow:hidden;background:#fff;box-shadow:0 0 0 1px rgba(20,30,60,.06),0 10px 28px -10px rgba(30,50,110,.3)}
142	.tool figure img{display:block;width:100%;height:auto}
143	.tool figcaption{font-size:13px;color:var(--muted);padding:8px 14px;background:rgba(255,255,255,.8);box-shadow:0 -1px 0 var(--hair)}
144	.tool .more{display:inline-block;margin-top:12px;font-size:14px;font-weight:600}
145	.proof{margin-top:8px;color:var(--muted);max-width:36em}
146	.nums{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px;margin-top:28px}
147	.nums>div{background:var(--gl);-webkit-backdrop-filter:var(--gl-f);backdrop-filter:var(--gl-f);box-shadow:var(--edge),var(--lift);border-radius:26px;padding:22px 22px 20px}
148	.nums b{display:block;font-size:clamp(30px,3.4vw,38px);letter-spacing:-.035em;line-height:1.1}
149	.nums span{display:block;margin-top:6px;color:var(--muted);font-size:14.5px;line-height:1.35}
150	.nums a{color:inherit}
151	#proof:has(.pending){display:none}
152	/* timeline: a race track, two stops a row, hairpin turns at the edges */
153	#built{max-width:1120px}
154	.tlw{position:relative;margin-top:30px}
155	.trk{position:absolute;left:0;top:0;width:100%;height:100%;overflow:visible;pointer-events:none}
156	.trk .road{fill:none;stroke:var(--road);stroke-width:18;stroke-linecap:round;stroke-linejoin:round}
157	.trk .edge{fill:none;stroke:rgba(255,255,255,.7);stroke-width:20;stroke-linecap:round;stroke-linejoin:round}
158	.trk .mid{fill:none;stroke:#fff;stroke-width:2.5;stroke-dasharray:1 9;stroke-linecap:round}
159	.trk .done{fill:none;stroke:var(--accent);stroke-width:3.5;stroke-linecap:round;filter:drop-shadow(0 0 5px rgba(10,102,214,.55))}
160	.trk .pt{fill:#fff;stroke:var(--accent);stroke-width:3}
161	.trk .pt.next{fill:#fff;stroke:#9A9AA2}
162	.tl{list-style:none;padding:0;margin:0;position:relative;z-index:1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-flow:row dense;column-gap:clamp(20px,3.5vw,44px);row-gap:clamp(24px,3.5vw,40px)}
163	.tl li{padding-top:30px;min-width:0}
164	.tl .when b{display:block;font-family:"Geist Mono",ui-monospace,Consolas,monospace;font-size:13px;color:var(--ink);font-weight:600;margin-bottom:10px}
165	.tl .when span{display:block;color:var(--muted);font-size:14px;line-height:1.35;margin-bottom:10px}
166	.twitter-tweet{border-radius:20px;padding:16px 18px;font-size:15px;line-height:1.5;max-width:550px}
167	.twitter-tweet p{margin:0 0 .5em}
168	.twitter-tweet a{word-break:break-word}
169	.twitter-tweet-rendered{margin:0!important;border-radius:20px;box-shadow:var(--lift)}
170	.followx{font-weight:600;font-size:15px}
171	/* about */
172	.about{display:grid;grid-template-columns:190px minmax(0,1fr);gap:clamp(24px,4vw,44px);align-items:center}
173	.ph{position:relative}
174	.ph .im{border-radius:30px;aspect-ratio:4/5;overflow:hidden;background:var(--tint);box-shadow:var(--edge),var(--lift)}
175	.ph img{width:100%;height:100%;object-fit:cover;object-position:top;display:block}
176	.about p{color:var(--muted);margin-top:10px;max-width:34em}
177	.about h2+p{margin-top:0}
178	.links{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}
179	.links a{text-decoration:none;color:var(--ink);border-radius:99px;padding:6px 18px;font-weight:600;font-size:14px;min-height:38px;display:inline-flex;align-items:center;transition:color .2s,transform .3s var(--ease)}
180	.links a:hover{color:var(--accent);transform:translateY(-2px)}
181	footer{max-width:960px;margin:0 auto;padding:28px 24px 48px;color:var(--muted);font-size:13px;display:flex;flex-wrap:wrap;gap:8px 24px;justify-content:space-between;align-items:center}
182	footer .wm{font-size:14px}footer .lg{width:22px;height:22px}
183	footer nav{display:flex;flex-wrap:wrap;gap:8px 20px}
184	@media(max-width:860px){.tool{grid-template-columns:1fr}.tool:nth-child(even) .txt{order:0}.rrp{grid-template-columns:1fr}.rrp figure{aspect-ratio:16/9}.nl{display:none}}
185	@media(max-width:720px){section{padding-left:20px;padding-right:20px}.strip{grid-template-columns:1fr 1fr}body{font-size:16px}.box{flex-wrap:wrap;padding:8px 8px 8px 18px;border-radius:28px}.box input{flex:1 1 100%;font-size:17px}.box button{width:100%}.tabs{flex-wrap:wrap}.tabs .sp{display:none}.tabs .cp{margin:0 0 6px auto}.hit{padding:20px}.hit-act .btn{width:100%}
186	 .reel{aspect-ratio:16/9}.ctl{right:20px;bottom:6%}
187	 .tl{grid-template-columns:minmax(0,1fr);padding:0 0 0 40px}.tl li:nth-child(n){grid-column:auto}
